from lib import *
S = SS('w66')
steps = [
    step("手工拼一个查询报文:查 example.com 的 A 记录,共 29 字节 = 12 字节头 + 问题区。头部 6 个 16 位字段:ID = 1a2b(随机数,响应原样带回);标志 = 0100,即 QR = 0(这是查询)、Opcode = 0、RD = 1(请求递归);QDCOUNT = 1,ANCOUNT = NSCOUNT = ARCOUNT = 0。问题区:07 \"example\" 03 \"com\" 00,每个标签前一个长度字节,以长度 0 结束,共 13 字节;之后 QTYPE = 1(A)、QCLASS = 1(IN)各 2 字节。用 dnspython 生成同一个查询得到的 29 个字节与手工拼的逐字节相同。", t=tl(S(1)), mark=lidx(S(1), '0000  1a 2b 01 00', '头部:ID=1a2b', '问题区:07'), done=lidx(S(1), '0010  6d 70', '对照 dnspython'), kv=KV([['头部', '12 字节:ID、标志、4 个计数'], ['标志 0x0100', 'QR=0 查询,RD=1'], ['名字', '长度前缀标签,0 结束'], ['总长', '29 字节']], ['标志 0x0100'])),
    step("1.1.1.1 的响应 61 字节(往返约 290 ms):ID 0x1a2b 与查询相同;标志 0x8180 = QR RD RA(是响应、请求了递归、服务器支持递归),RCODE = NOERROR;问题 1 / 回答 2 / 授权 0 / 附加 0。两条 A 记录:每条的名字都写成 2 字节的 c0 0c——高两位 11 表示“指针”,低 14 位 = 12 是报文内的偏移(从 ID 开头算),指向第 12 字节,也就是问题区里的 example.com;随后是类型 1、类 1、TTL(这次是 272 秒)、RDLENGTH = 4、4 字节地址(104.20.23.154 和 172.66.147.243)。两条记录的名字都用了压缩指针。", t=tl(S(2)), mark=lidx(S(2), '0010  6d 70 6c 65 03 63 6f 6d 00 00 01 00 01 c0 0c', '回答区里记录的名字'), done=lidx(S(2), '0000  1a 2b 81 80', '[an] example.com', '报文里共有'), kv=KV([['标志 0x8180', 'QR RD RA'], ['记录名 c0 0c', '指针,指向偏移 12'], ['回答', '2 条 A,TTL 272']], ['记录名 c0 0c'])),
    step("同一个名字,不同提问方式的标志。递归解析器 1.1.1.1:RD = 1 → QR RD RA,2 条回答;RD = 0 → QR RA(RD 位被清除,但仍然给出了回答,应该是缓存里有),2 条回答。example.com 下一个不存在的子名字 → RCODE NOERROR、回答 0、授权 1(NODATA 加 SOA),108 字节;不存在的顶级域 .invalid → RCODE NXDOMAIN、回答 0、授权 1(SOA),117 字节。example.com 的权威服务器(NS 记录是 hera.ns.cloudflare.com 和 elliott.ns.cloudflare.com;我直接问其中一个公网地址):标志 QR AA RD——AA 位置位(权威回答)、没有 RA(它不做递归);RD = 0 时是 QR AA;问它不托管的 www.kernel.org → RCODE REFUSED,32 字节,回答 0。", t=tl(S(3)), mark=lidx(S(3), '递归解析器,RD=0', '权威服务器,RD=1', '权威服务器,不是它托管的名字'), done=lidx(S(3), '递归解析器,RD=1,存在的名字', 'example.com 下不存在的子名字', '不存在的顶级域', 'example.com 的 NS 记录'), kv=KV([['递归解析器', 'QR RD RA'], ['权威服务器', 'QR AA(无 RA)'], ['不存在的 .invalid', 'NXDOMAIN + SOA'], ['不是它托管的名字', 'REFUSED']], ['权威服务器'])),
    step("名字压缩省了多少字节:把真实响应里每个域名(问题名、记录名、RDATA 里的域名)都按完整展开计算大小,对比实际字节数。example.com NS:实际 84 字节,展开估算 126 字节,省 42 字节(33%);example.com MX:44 字节 vs 55,省 11(20%);www.iana.org A:107 字节 vs 181,省 74(41%);iana.org NS:113 vs 180,省 67(37%);iana.org SOA:80 vs 104,省 24(23%)。含多个记录、名字重复多的响应省得最多。“展开估算”是我按名字长度算出来的,不是服务器真的发过未压缩的版本。", t=tl(S(4)), mark=lidx(S(4), 'www.iana.org A', 'iana.org NS'), done=lidx(S(4), 'example.com NS', 'example.com MX', 'iana.org SOA'), b=bars([['example.com NS', 33, '33%'], ['example.com MX', 20, '20%'], ['www.iana.org A', 41, '41%'], ['iana.org NS', 37, '37%'], ['iana.org SOA', 23, '23%']], 41, mark=[2], done=[0, 1, 3, 4]), kv=KV([['www.iana.org A', '107 vs 181 字节,省 41%'], ['example.com MX', '44 vs 55 字节,省 20%'], ['说明', '展开大小是估算']], ['www.iana.org A'])),
    step("两个服务器行为细节。(1)大小写:发 eXaMpLe.CoM,响应问题区里写的是 eXaMpLe.CoM,回答里的记录名也是 eXaMpLe.CoM;发 EXAMPLE.COM 同样原样回显。DNS 把大小写当作相同的名字,但服务器保留提问的写法,所以客户端可以随机化大小写(“0x20”),用回显是否一致来增加伪造响应的难度。(2)非法的长度字节:长度字节是 64(超过标签上限 63)的名字,3 次都没有响应;长度字节是 0x80(保留的高两位 10)的名字,3 次也没有响应——1.1.1.1 对这两种畸形报文直接丢弃,没有回 FORMERR。", t=tl(S(5)), mark=lidx(S(5), '发一个长度字节为 64', '发一个长度字节为 0x80'), done=lidx(S(5), '发 eXaMpLe.CoM', '发 EXAMPLE.COM'), kv=KV([['大小写', '服务器原样回显'], ['长度字节 64', '3 次无响应'], ['长度字节 0x80', '3 次无响应']], ['大小写'])),
]
A = mkartw('w66', 66, '网络协议,DNS,报文格式,名字压缩,RCODE,AA,RD,RA,真实验证,动画演示',
    '逐字节解析 DNS 报文:29 字节查询(12 字节头 + 问题区);1.1.1.1 的 61 字节响应,记录名是指向偏移 12 的压缩指针 c0 0c;递归解析器标志 QR RD RA,权威服务器 QR AA 且无 RA,不托管的名字 REFUSED;名字压缩省 20%~41%;大小写原样回显,非法标签长度被丢弃。',
    'DNS 是互联网的电话簿,但它的报文只有区区几十个字节:12 字节头、问题区、几条资源记录。这篇手工拼一个查询、逐字节解析 1.1.1.1 的响应,看标志位、RCODE、名字压缩指针,并对照递归解析器与权威服务器的行为。',
    [('29 → 61 字节', '查 example.com 的 A 记录:查询与响应的报文大小'), ('c0 0c', '响应里记录名的 2 字节压缩指针,指向报文偏移 12 的问题区名字'), ('20% ~ 41%', '名字压缩让真实响应省下的字节比例(按展开估算)')],
    [('查询报文', '<p>12 字节头(ID、标志、QDCOUNT 等 4 个计数)加问题区;名字是“长度 + 标签”序列,以 0 结束。</p>'),
     ('响应与压缩指针', '<p>响应里的记录名写成 c0 0c:指针指向报文内偏移 12。TTL、RDLENGTH、RDATA 紧随其后。</p>'),
     ('标志位', '<p>递归解析器 QR RD RA;权威服务器 QR AA,没有 RA;不托管的名字得 REFUSED;不存在的顶级域得 NXDOMAIN + SOA。</p>'),
     ('名字压缩', '<p>真实响应里压缩省了 20%~41% 的字节,多记录响应省得更多。</p>'),
     ('回显与畸形输入', '<p>服务器原样回显大小写;长度字节 64 和 0x80 的畸形名字被 1.1.1.1 丢弃,没有回 FORMERR。</p>')],
    steps,
    [ENV_W + '。向 1.1.1.1 与 example.com 的权威服务器(Cloudflare 的 NS)发送普通 DNS 查询,另有两个畸形名字只发给 1.1.1.1;往返约 290 ms;“展开估算”是我按名字长度计算的,不是实测;TTL 每次运行不同',
     '没有验证:压缩指针的循环或超界(服务器如何处理恶意报文);EDNS0 的 OPT 记录(下面 DNS over TCP 与 EDNS0 一篇展开);IPv6 传输的 DNS;不同递归解析器(8.8.8.8、本机配置的解析器)对 RD=0 的处理差别;为什么 1.1.1.1 对畸形名字不回 FORMERR(只看到“无响应”)'],
    'DNS 报文')
